import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The icons used by the app.
 *
 * Generated from Google's Material Symbols (Rounded, Apache License 2.0). Only the icons that
 * are actually used are included, which keeps the APK far smaller than shipping an icon library.
 */
object Ic {
    private val cache = HashMap<String, ImageVector>()

    /** Builds a 24dp icon from Material Symbols path data (view box 0 -960 960 960). */
    private fun symbol(name: String, path: String): ImageVector = cache.getOrPut(name) {
        ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f)
            .addGroup(translationY = 960f)
            .addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
            .clearGroup()
            .build()
    }

    /** Builds a 24dp line icon from path data drawn on a 24 x 24 grid. */
    private fun line(name: String, path: String, width: Float = 2f): ImageVector = cache.getOrPut(name) {
        ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f)
            .addPath(
                pathData = addPathNodes(path), stroke = SolidColor(Color.Black), strokeLineWidth = width,
                strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
            )
            .build()
    }

    /** Material Symbols has no metronome, so this one is drawn by hand. */
    val Metronome: ImageVector get() = line("Metronome", "M9 3h6l4 18H5L9 3zM12 16l5-9M7.3 14h9.4")

    /** The wordmark of the app (letters M, P, S with equalizer bars inside the M). */
    val Logo: ImageVector
        get() = cache.getOrPut("Logo") {
            ImageVector.Builder("Logo", 72.dp, 25.5.dp, 714f, 254f)
                .addPath(
                    pathData = addPathNodes(LOGO_LETTERS), stroke = SolidColor(Color.Black), strokeLineWidth = 25f,
                    strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
                )
                .addPath(
                    pathData = addPathNodes(LOGO_BARS), stroke = SolidColor(Color.Black), strokeLineWidth = 18f,
                    strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round,
                )
                .build()
        }

